<div class="titlebar"><div><h2><?= $esc($k['keperluan']) ?></h2><p><?= $esc($snap['opd_tahun']['nama_opd']??$snap['opd']['nama_opd']) ?> · <?= $k['tahun'] ?></p></div><div class="actions"><a class="button secondary" href="<?= $url() ?>">Kembali</a><?php if($actor['role']!=='viewer'): ?><a class="button" href="<?= $url('form/'.$k['id_kegiatan']) ?>">Ubah kegiatan</a><form method="post" action="<?= $url('remove/kegiatan/'.$k['id_kegiatan']) ?>" data-confirm="Tandai kegiatan ini dihapus?"><?= $token ?><button class="danger">Hapus</button></form><?php endif; ?></div></div>
<div class="cards"><div class="card"><small>Pagu</small><strong class="money">Rp <?= $rupiah($k['pagu']) ?></strong></div><div class="card"><small>Nilai kontrak</small><strong class="money">Rp <?= $rupiah($k['nilai']) ?></strong></div><div class="card"><small>Status</small><strong><?= ['B'=>'Belum','P'=>'Proses','S'=>'Selesai'][$k['st_kontrak']] ?></strong></div><div class="card"><small>Lokasi</small><?= $esc($k['lokasi_pekerjaan']) ?></div></div>
<?php foreach(['fisik'=>'Realisasi fisik','keuangan'=>'Realisasi keuangan'] as $kind=>$title): $pk=$kind==='fisik'?'id_detail':'id_keuangan';$date=$kind==='fisik'?'tanggal':'tgl_realisasi';$val=$kind==='fisik'?'realisasi':'nilai'; ?>
<section class="panel"><h2><?= $title ?></h2><p class="muted"><?= $kind==='fisik'?'Catat persentase kumulatif pada tanggal aktual. Laporan memakai catatan terakhir, bukan nilai tertinggi.':'Catat transaksi pembayaran, bukan total kumulatif. Jumlah transaksi tidak boleh melebihi nilai kontrak.' ?></p>
<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Nilai <?= $kind==='fisik'?'(%)':'(Rp)' ?></th><th>Keterangan</th><th>Aksi</th></tr></thead><tbody><?php foreach($snap[$kind] as $r)if(!$r['deleted_at']): ?><tr><td><?= $esc($r[$date]) ?></td><td class="num"><?= $rupiah($r[$val]) ?></td><td><?= $esc($r['keterangan']) ?></td><td><?php if($actor['role']!=='viewer'): ?><details><summary>Ubah</summary><form method="post" action="<?= $url('save/'.$kind) ?>"><?= $token ?><input type="hidden" name="id" value="<?= $r[$pk] ?>"><input type="hidden" name="id_kegiatan" value="<?= $k['id_kegiatan'] ?>"><label>Tanggal<input required type="date" name="tanggal" value="<?= $esc($r[$date]) ?>"></label><label>Nilai<input required type="number" min="0" step="0.01" name="nilai" value="<?= $esc($r[$val]) ?>"></label><label>Keterangan<input name="keterangan" maxlength="500" value="<?= $esc($r['keterangan']) ?>"></label><button>Simpan</button></form></details><form class="inline" method="post" action="<?= $url('remove/'.$kind.'/'.$r[$pk]) ?>" data-confirm="Hapus realisasi ini?"><?= $token ?><button class="danger">Hapus</button></form><?php endif; ?></td></tr><?php endif; ?></tbody></table></div>
<?php if($actor['role']!=='viewer'): ?><details><summary>+ Tambah <?= strtolower($title) ?></summary><form class="grid" method="post" action="<?= $url('save/'.$kind) ?>"><?= $token ?><input type="hidden" name="id_kegiatan" value="<?= $k['id_kegiatan'] ?>"><label>Tanggal aktual<input required type="date" min="<?= $k['tahun'] ?>-01-01" max="<?= $k['tahun'] ?>-12-31" name="tanggal"></label><label><?= $kind==='fisik'?'Fisik kumulatif (%)':'Pembayaran (Rp)' ?><input required type="number" min="0" <?= $kind==='fisik'?'max="100"':'' ?> step="0.01" name="nilai"></label><label>Keterangan<input name="keterangan" maxlength="500"></label><button>Simpan realisasi</button></form></details><?php endif; ?></section>
<?php endforeach; ?>
<section class="panel"><h2>Dokumentasi kegiatan</h2><div class="photo-grid"><?php foreach($snap['fisik'] as $d)if(!$d['deleted_at'])foreach($d['dokumentasi'] as $photo)if(!$photo['deleted_at']): ?><article><img loading="lazy" src="<?= $url('file/'.$photo['id_dokumentasi']) ?>" alt="<?= $esc($photo['keterangan']) ?>"><p><?= $esc($photo['keterangan']) ?></p><small>Fisik <?= $esc($d['tanggal']) ?> · <?= $esc($d['realisasi']) ?>%<br>Tanggal foto: <?= $esc($photo['tanggal']?:'Tidak tersedia') ?></small><?php if($actor['role']!=='viewer'): ?><form method="post" action="<?= $url('remove/foto/'.$photo['id_dokumentasi']) ?>" data-confirm="Hapus dokumentasi ini?"><?= $token ?><button class="danger">Hapus</button></form><?php endif; ?></article><?php endif; ?></div>
<?php if($actor['role']!=='viewer'): ?><details><summary>+ Unggah foto</summary><form class="grid" enctype="multipart/form-data" method="post" action="<?= $url('save/foto') ?>"><?= $token ?><input type="hidden" name="id_kegiatan" value="<?= $k['id_kegiatan'] ?>"><label>Catatan fisik<select required name="id_detail"><option value="">Pilih catatan fisik</option><?php foreach($snap['fisik'] as $d)if(!$d['deleted_at']): ?><option value="<?= $d['id_detail'] ?>"><?= $esc($d['tanggal']) ?> · <?= $esc($d['realisasi']) ?>%</option><?php endif; ?></select></label><label>Foto (JPEG/PNG/WebP, maks. 5 MB)<input required type="file" accept="image/jpeg,image/png,image/webp" name="foto"></label><label>Tanggal foto (opsional)<input type="date" name="tanggal"></label><label class="full">Keterangan<input name="keterangan" maxlength="500"></label><button>Unggah dokumentasi</button></form></details><?php endif; ?></section>
